var TODAY={"date": "2026-07-07", "dateDisplay": "2026年7月7日 星期二", "papers": [{"title": "LXD-SLAM: LiDAR+X Dense SLAM — 32种可配置传感器组合的即插即用框架", "venue": "arXiv:2606.27811, 2026.06.26", "authors": "Zhong Wang 等", "stars": 5, "contribution": "首个支持LiDAR+Camera+IMU+Wheel+GNSS五传感器任意组合(共31种)的即插即用SLAM框架，统一IESKF自适应分层预测+逐点-网格距离最小化，GPGP子网格局部地图+扩展Scan Context多模态回环。", "approach": "统一IESKF+自适应分层预测+点-网格距离最小化+GPGP子网格+扩展Scan Context回环", "innovation": "同一套代码支持31种传感器组合；自适应分层预测根据可用传感器自动切换融合策略——对履带平台渐进式传感器升级极为友好", "recommend": "must-read", "tags": [{"text": "精读+复现", "cls": "recommend"}, {"text": "多传感器融合", "cls": "core"}, {"text": "即插即用", "cls": "method"}], "url": "https://arxiv.org/abs/2606.27811"}, {"title": "Ultra-Fusion: 韧性紧耦合多传感器融合SLAM——因子级退化感知+在线标定", "venue": "arXiv:2606.21223, 2026.06.19", "authors": "Yihong Tian 等", "stars": 5, "contribution": "统一滑动窗口估计器支持WIO/VIO/LIO/LVIO+可选轮速/GNSS；首创因子级可靠性调度逐因子抑制退化(非传感器级)；在线LiDAR-IMU时空标定无需离校。60+SLAM系统5基准大规模评测。", "approach": "滑动窗口因子图+因子级可靠性调度+在线时空标定+退化感知门控+5基准60+系统评测", "innovation": "因子级(非传感器级)可靠性调度更细粒度；滑窗内在线标定消除手动标定——丘陵振动环境标定漂移问题直接受益", "recommend": "must-read", "tags": [{"text": "精读", "cls": "recommend"}, {"text": "退化处理", "cls": "core"}, {"text": "在线标定", "cls": "method"}], "url": "https://arxiv.org/abs/2606.21223"}, {"title": "MIL-LC: 磁力计-惯性-LiDAR融合定位——纹理稀疏/几何重复环境抗退化", "venue": "arXiv:2606.25796, 2026.06.24", "authors": "(发布于2026.06.24)", "stars": 4, "contribution": "首次将环境磁场(AMF)与惯性+LiDAR数据紧耦合定位，利用建筑结构/地质特征产生的独特磁场指纹在GNSS拒止/几何重复场景实现鲁棒定位。办公室/酒店/地下停车场验证。", "approach": "MEMS磁力计紧耦合IMU+LiDAR+环境磁场特征匹配+滑动窗口因子图", "innovation": "磁场指纹作为第四模态填补几何退化空白——丘陵环境中金属矿物/岩层可能产生独特磁场特征", "recommend": "must-read", "tags": [{"text": "精读", "cls": "recommend"}, {"text": "磁性定位", "cls": "method"}, {"text": "退化抵抗", "cls": "core"}], "url": "https://arxiv.org/abs/2606.25796"}, {"title": "KISS-IMU: 自监督惯性里程计——运动平衡学习+不确定性感知推理 (ICRA 2026)", "venue": "ICRA 2026 — SPARO Lab, Inha University (WiRA Outstanding Student Paper Winner)", "authors": "Jiwon Choi, Hogyun Kim, Geonmo Yang, Juhui Lee, Younggun Cho", "stars": 4, "contribution": "自监督学习IMU里程计无需真值轨迹标注，运动平衡学习策略防止IMU偏差漂移，不确定性感知推理输出逐帧置信度评估——LiDAR退化时的理想回退方案。", "approach": "自监督学习+运动平衡损失+不确定性感知贝叶斯推理+端到端IMU里程计", "innovation": "完全自监督无需真值轨迹；运动平衡策略针对性抑制长时间积分漂移；逐帧不确定性可指导融合权重", "recommend": "must-read", "tags": [{"text": "精读", "cls": "recommend"}, {"text": "IMU里程计", "cls": "core"}, {"text": "自监督", "cls": "method"}]}, {"title": "RadLoc: 基于雷达的3-DoF全局定位——快速鲁棒轻量空间描述符 (IROS 2026)", "venue": "IROS 2026 — SPARO Lab, Inha University", "authors": "Hogyun Kim, Jiwon Choi, Jungwoo Lee, Younggun Cho", "stars": 4, "contribution": "以4D毫米波雷达替代LiDAR实现全局定位，设计轻量空间描述符实现快速检索+鲁棒匹配，适用于雨/雾/尘LiDAR失效场景——全天候定位补充方案。", "approach": "毫米波雷达空间描述符+全局检索匹配+3-DoF定位+轻量网络+实时推理", "innovation": "雷达替代LiDAR全局定位——丘陵雨雾尘天气下全天候定位补充方案", "recommend": "skim", "tags": [{"text": "泛读", "cls": "venue"}, {"text": "雷达定位", "cls": "method"}, {"text": "全天候", "cls": "core"}]}, {"title": "MAT: 速度感知可通行性——从静态代价到运动依赖代价场", "venue": "2026.02更新 / 多山地验证", "authors": "(Motion-Aware Traversability, 2026)", "stars": 5, "contribution": "范式变革——可通行性代价不仅是位置的函数更是机器人速度的函数。速度感知代价模型在多山地形减少75%路径绕行距离、显著提升导航成功率。", "approach": "速度依赖代价场+风险感知规划+速度-路径联合优化+多山地实机验证", "innovation": "可通行性从静态属性升级为运动耦合属性——履带打滑率恰与速度强相关，天然适配；75%绕行减少极具工程价值", "recommend": "must-read", "tags": [{"text": "精读", "cls": "recommend"}, {"text": "可通行性", "cls": "core"}, {"text": "速度感知", "cls": "method"}]}, {"title": "三维波浪地形下履带/滑移转向底盘DRL逃逸与路径点跟踪", "venue": "Computers and Electronics in Agriculture, Vol.241, 2025-2026", "authors": "Song Bi, Yun Ding", "stars": 5, "contribution": "SSMR轮胎离地/悬空被困：本体感知数据(IMU+轮速+电流)识别被困状态+深度强化学习(DRL)生成连续空间逃逸动作，真实果园实验90%脱困成功率。", "approach": "本体感知被困识别+LSTM状态编码+DRL连续动作逃逸策略+真实波浪地形验证", "innovation": "本体感知被困识别无需外部视觉传感器；DRL连续空间逃逸比离散动作更平滑——丘陵履带脱困方案直接可用", "recommend": "must-read", "tags": [{"text": "精读", "cls": "recommend"}, {"text": "履带脱困", "cls": "core"}, {"text": "DRL", "cls": "method"}]}, {"title": "MS-AIS: 多传感器空地协同自主检测机器人系统 (IROS 2026)", "venue": "IROS 2026 — ARA Lab, University of Nevada, Reno", "authors": "C. P. Le, P. Walunj, A. Nguyen, V. C. Nguyen, A. Netchaev, H. La", "stars": 3, "contribution": "UGV-UAV空地协同自主检测系统，LiDAR+RGB+热红外多传感器融合感知，面向基础设施巡检/灾后评估的完整端到端方案。", "approach": "UGV-UAV空地协同+多传感器融合感知+自主检测路径规划+热红外缺陷检测", "innovation": "空地协同多传感器巡检一体化——丘陵环境基础设施巡检场景可直接参考架构", "recommend": "skim", "tags": [{"text": "泛读", "cls": "venue"}, {"text": "空地协同", "cls": "method"}, {"text": "巡检", "cls": "core"}]}, {"title": "STONE Dataset: 大规模多模态环视3D可通行性数据集 (ICRA 2026)", "venue": "ICRA 2026 — Seoul National University", "authors": "Konyul Park, Hyungchan Cho, Hongjae Shin 等 — SNU", "stars": 5, "contribution": "首个LiDAR(128线)+6 RGB相机+3×4D成像雷达全同步环视可通行性数据集；全自动几何标注管线生成轨迹引导3D可通行性GT；草地/农田/工地/湖畔/昼夜全覆盖。", "approach": "128线LiDAR+6环视相机+3×4D雷达多模态同步+自动几何标注+体素级3D可通行性预测基准", "innovation": "环视多模态+全自动GT生成管线——标注模式可迁移到丘陵履带自采数据，快速构建专属数据集", "recommend": "must-read", "tags": [{"text": "精读+数据", "cls": "recommend"}, {"text": "数据集", "cls": "core"}, {"text": "自动标注", "cls": "method"}], "url": "https://konyul.github.io/STONE-dataset/"}, {"title": "SA-LIVO: 子空间感知LiDAR-Inertial-Visual里程计——方向选择性退化处理", "venue": "arXiv:2606.25699, 2026.06.24", "authors": "港大MaRS Lab", "stars": 4, "contribution": "信息矩阵特征分解后逐方向软门控，比全局门控更精细处理LiDAR几何退化+视觉纹理退化独立故障。CPU 12.3ms/帧高效推理。", "approach": "联合信息矩阵特征分解+逐方向软门控+CPU实时推理", "innovation": "方向选择性融合比全局门控更精细——丘陵中不同方向退化程度不同(LiDAR斜坡退化/视觉弱纹理)可独立处理", "recommend": "must-read", "tags": [{"text": "精读", "cls": "recommend"}, {"text": "退化处理", "cls": "method"}, {"text": "LIVO", "cls": "core"}], "url": "https://arxiv.org/abs/2606.25699"}], "projects": [{"name": "Traversability-Nav2 (越野导航代价地图插件)", "url": "https://github.com/sacrover/traversability-nav2", "stars": "活跃 (awesome-ecosyste.ms收录)", "highlights": "ROS2 Navigation2可通行性代价地图插件；集成地形可通行性评估到标准Nav2导航栈；越野/非结构化环境导航增强；可直接复现部署", "difficulty": "★★★☆☆ 需Nav2定制经验", "value": "★★★★★ 丘陵履带Nav2部署的核心缺失模块"}, {"name": "Lidarbot (ROS2 Humble全栈移动机器人)", "url": "https://github.com/thenoobinventor/lidarbot", "stars": "ROS2 Humble社区项目 (2026)", "highlights": "RPLiDAR A1+MPU6050+robot_localization EKF+SLAM Toolbox+Nav2全栈集成；完整文档+教程；履带/差分驱动双模式", "difficulty": "★★☆☆☆ 入门级全栈参考", "value": "★★★★☆ ROS2 Nav2全栈入门最佳实践参考"}, {"name": "Perceptor (ROS2 Jazzy综合机器人导航平台)", "url": "https://github.com/mvipin/perceptor", "stars": "ROS2 Jazzy社区项目 (2026)", "highlights": "iRobot Create 2+LiDAR+IMU+EKF+SLAM+Nav2完整栈；禁区+变速限制+视觉航点+实时碰撞监控；Jazzy最新发行版", "difficulty": "★★☆☆☆ 文档齐全", "value": "★★★★☆ 禁区管理+变速限制对丘陵安全导航有参考价值"}, {"name": "MOLA v1 (模块化LiDAR定位建图框架)", "url": "https://github.com/MOLAorg/mola", "stars": "社区维护 (2026.06更新)", "highlights": "YAML管道式LIO/GNSS融合；mola_mapper_2d+3d后端；MulRan/EuRoC/KITTI学术数据集输入；ROS2 Humble/Jazzy全覆盖", "difficulty": "★★★☆☆ 需YAML管道配置", "value": "★★★★☆ 多传感器可定制性强于硬编码方案"}, {"name": "elevation_mapping_cupy_ros2 (GPU高程建图)", "url": "https://github.com/amilearning/elevation_mapping_cupy_ros2", "stars": "ETH RSL移植中 (2026)", "highlights": "GPU(CuPy)加速高程建图；CNN可通行性滤波；多模态图层(几何/语义/RGB)；DARPA地下赛实战验证", "difficulty": "★★★☆☆ 需CUDA+ROS2适配", "value": "★★★★★ 丘陵GPU高程建图核心基础设施"}], "trends": [{"title": "即插即用+自适应调度——SLAM从专用走向通用操作系统", "body": "LXD-SLAM(31种组合)和Ultra-Fusion(因子级调度)代表SLAM正走向'传感器操作系统'模式——同一套代码根据硬件配置自动适配。对履带平台意味着从LiDAR-only→LiDAR+IMU→LiDAR+IMU+RTK的渐进式升级无需更换SLAM框架，极大降低工程集成成本。"}, {"title": "磁场指纹+毫米波雷达——抗退化模态池从三维扩展到六维", "body": "MIL-LC引入环境磁场作为第四模态，RadLoc用4D雷达替代LiDAR全局定位。结合已有热红外SLAM(PL-LIT/LIT-GS)，抗退化武器库已从LiDAR+IMU+Vision扩展到Magnetic+Radar+Thermal六模态。丘陵全天候部署不再依赖单一传感器。"}, {"title": "可通行性建模三方向并进——速度感知+本体感知+几何自监督", "body": "MAT将可通行性与速度耦合(减少75%绕行)、COTRATE以本体感知消除标注、GSAT以几何异常检测自监督。三个方向互补——速度+感知+几何覆盖可通行性全维度。履带平台的打滑率恰好是速度与本体感知的天然桥梁变量。"}, {"title": "IMU-only里程计从需要标定走向自监督学习——回退层更可靠", "body": "KISS-IMU(ICRA 2026 WIRA获奖)以自监督学习消除IMU里程计对真值轨迹的依赖，运动平衡策略针对性抑制长时漂移。在LiDAR退化+GNSS拒止双重故障时，KISS-IMU提供完全独立的惯性回退层——比轮速里程计更通用。"}, {"title": "履带平台专属方案深化——从标定/融合/退化到脱困全链路覆盖", "body": "Bi&Ding DRL脱困策略(90%成功率)+Okawara神经运动学标定+FusionCore第23状态(轮速偏航偏置)+SENTINEL退化检测轮速回退——履带专属SLAM技术栈已覆盖标定/融合/退化/脱困全链路，研究空白正在闭合。"}, {"title": "全自动数据标注管线突破数据瓶颈——从手工到算法驱动", "body": "STONE(ICRA 2026)全自动几何标注GT生成+Trinity训练无关分割——可通行性数据集构建从手工标注转向算法自动生成。丘陵履带平台自采数据可直接适配STONE标注流程，快速构建专属数据集。"}], "opportunities": {"masters": [{"title": "履带平台速度感知可通行性建模——打滑率与地形坡度耦合", "detail": "MAT速度感知框架迁移到履带平台，将履带打滑率(Okawara在线标定或FusionCore轮速偏航偏置)作为速度-可通行性耦合的物理约束。2.5D高程(FastDEM)+速度依赖代价场+打滑率物理模型三合一。", "meta": "Velocity-Aware Traversability Modeling with Slip-Rate Coupling for Tracked Platforms in Hilly Terrain"}, {"title": "LXD-SLAM即插即用框架在履带平台的渐进式部署与传感器增益量化", "detail": "利用LXD-SLAM同一框架分别测试LiDAR-only/LiDAR+IMU/LiDAR+IMU+RTK三种组合在丘陵场景的精度差异，量化每种传感器增量带来的收益，为履带平台传感器选型提供量化依据。", "meta": "系统性强+实验丰富+直接解决传感器选型与部署路径问题"}, {"title": "本体感知+DRL双驱动履带脱困策略——Bi&Ding方法扩展", "detail": "Bi&Ding被困识别扩展为多维本体感知(IMU+轮速+电流+扭矩+振动频谱)，DRL动作空间加入差速制动和低速扭矩控制，验证丘陵多种困局(泥泞/沟壑/陡坡松土)的脱困成功率。", "meta": "Proprioceptive Multi-Modal Entrapment Detection and DRL-Based Escape for Tracked Platforms in Hilly Terrain"}], "topConference": [{"title": "Ultra-Fusion因子级调度+速度感知可通行性+履带神经运动学联合因子图SLAM", "detail": "Ultra-Fusion因子级可靠性调度+速度感知可通行性(MAT)+履带神经运动学标定(Okawara)统一到单因子图——三个2026前沿方向首次交汇在履带平台。", "meta": "目标: RSS 2027 / IEEE T-RO / ICRA 2027"}, {"title": "磁场指纹+KISS-IMU+毫米波雷达三级抗退化回退履带SLAM", "detail": "MIL-LC环境磁场定位+RadLoc雷达定位+KISS-IMU自监督惯性——三模态抗退化回退层，形成LiDAR正常→LiDAR退化→磁场/雷达回退→惯性兜底四级退化层次。", "meta": "目标: IROS 2027 / IEEE RA-L + ICRA 2027"}, {"title": "基于STONE标注范式+履带本体感知的丘陵多模态可通行性数据集", "detail": "STONE全自动几何标注管线适配履带平台(加入打滑率+IMU振动+扭矩)，构建首个履带专属LiDAR+RGB+IMU+本体感知的丘陵可通行性数据集，作为领域基准开源。", "meta": "目标: IEEE RA-L + ICRA 2027 / 领域基准数据集贡献"}], "deployable": [{"title": "【短期 1-2月】LXD-SLAM + FastDEM + Nav2 Traversability插件", "detail": "LXD-SLAM (31种组合渐进式：先LiDAR+IMU再+RTK) + FastDEM 100Hz高程建图 + Traversability-Nav2代价地图插件。全部ROS2，即插即用特性保证增量式部署。", "meta": "预计 1-2 月，LXD-SLAM 31种组合的即插即用特性是对工程部署的最大利好"}, {"title": "【中期 3-6月】Ultra-Fusion退化调度 + 速度感知代价场 + MOLA模块化建图", "detail": "Ultra-Fusion因子级退化调度替代简单传感器切换→速度感知可通行性定制代价地图→MOLA YAML管道式LiDAR+IMU+GNSS建图→Smac Hybrid-A*/MPPI越野规划。", "meta": "预计 3-6 月，需开发速度感知代价地图插件+Ultra-Fusion到Nav2的桥接模块"}, {"title": "【长期 6-12月】磁场/雷达回退+DRL脱困+STONE标注+完整越野导航栈", "detail": "MIL-LC磁场+KISS-IMU惯性+RadLoc雷达三级退化回退+Bi&Ding DRL脱困+STONE自动标注履带数据集+Ultra-Fusion统一因子图——构建SLAM→退化处理→脱困→规划→长期维护完整栈。", "meta": "预计 6-12 月，需硬件(磁力计+4D雷达)+大量自采数据+系统集成开发"}]}, "actions": [{"priority": "P0", "title": "精读 LXD-SLAM + Ultra-Fusion 即插即用+退化调度双框架，对比履带平台适用性", "time": "1周", "type": "论文"}, {"priority": "P0", "title": "精读 MAT 速度感知可通行性 + Bi&Ding 履带脱困DRL方案", "time": "1周", "type": "论文"}, {"priority": "P0", "title": "精读 STONE Dataset 自动标注管线，设计履带平台适配方案", "time": "1周", "type": "论文+设计"}, {"priority": "P1", "title": "精读 KISS-IMU 自监督IMU里程计 + MIL-LC 磁场定位抗退化", "time": "1周", "type": "论文"}, {"priority": "P1", "title": "部署 LXD-SLAM 在履带平台渐进式测试 (LiDAR→LiDAR+IMU→+RTK)", "time": "2-3周", "type": "工程"}, {"priority": "P1", "title": "调研 Traversability-Nav2 插件 + 自定义速度感知代价地图方案", "time": "1-2周", "type": "工程+调研"}, {"priority": "P2", "title": "探索 磁场传感器/4D雷达在丘陵环境中的信号特征与部署可行性", "time": "1-2周", "type": "调研"}, {"priority": "P2", "title": "研究 STONE→履带自动标注迁移 + 丘陵数据集初步采集方案", "time": "1-2周", "type": "数据+实验"}]};
